{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.ras_easyecom_sales_consolidated_intermediate as SELECT \'Easyecom\' as Data_Source ,cast(NULL as string) AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,safe_cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,safe_cast(safe_cast(ORDER_DATE as datetime) as date) AS Order_Date ,SAFE_CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,\"\" AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN SAFE_CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN SAFE_CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,SAFE_CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,\"\" AS ACQUISITION_PRODUCT ,safe_cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,cast(NULL as date) AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(category) AS PRODUCT_CATEGORY ,UPPER(mapped_category) AS PRODUCT_SUB_CATEGORY ,coalesce(case when b.commonsku =\'\' then null else b.commonsku end,b.master_SKU) commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,\"\" Source_name ,null Mapped_Source_Name ,null Order_Type FROM maplemonk.RAS_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' ) ; CREATE OR REPLACE TABLE `maplemonk.ras_easyecom_Final_customerID` AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), r\'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM `maplemonk.ras_easyecom_sales_consolidated_intermediate` ) a ), int AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT REPLACE(phone, \' \', \'\') AS contact_num, email FROM `maplemonk.ras_easyecom_sales_consolidated_intermediate` ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM int WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.ras_easyecom_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS Acquisition_D, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.ras_easyecom_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.ras_Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.ras_Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; create or replace table maplemonk.ras_luxury_sales_consolidated as select * from `MAPLEMONK.ras_oil_sales_consolidated` union all select * from `MAPLEMONK.ras_mini_sales_consolidated` union all select * from `MAPLEMONK.ras_dot_in_sales_consolidated` union all select * from `MAPLEMONK.moody_sales_consolidated` union all select * from `MAPLEMONK.ras_easyecom_sales_consolidated` ; ALTER TABLE maplemonk.ras_luxury_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.ras_luxury_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.ras_luxury_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.ras_luxury_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.ras_luxury_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.ras_luxury_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR Acquisition_D IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.ras_luxury_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.ras_luxury_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by Order_Time asc, selling_price desc) rw FROM maplemonk.ras_luxury_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.ras_luxury_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            